class Stock(initial: Int) {
    init { require(initial >= 0) }
    var remaining: Int = initial
        private set
    val soldOut: Boolean get() = remaining == 0
    fun decrease(quantity: Int) {
        require(quantity > 0 && quantity <= remaining)
        remaining -= quantity
    }
}

