sealed interface ReserveResult {
    data class Reserved(val remaining: Int) : ReserveResult
    data object SoldOut : ReserveResult
}
fun reserve(stock: Int, quantity: Int): ReserveResult {
    require(stock >= 0 && quantity > 0)
    return if (quantity <= stock)
        ReserveResult.Reserved(stock - quantity)
    else ReserveResult.SoldOut
}
